package com.phira.lab;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.json.*;
public final class OriginalStoreTest {
 static void check(boolean c,String message){if(!c)throw new AssertionError(message);}
 static void write(File f,JSONObject data)throws Exception{Files.write(f.toPath(),data.toString().getBytes(StandardCharsets.UTF_8));}
 static JSONObject read(File f)throws Exception{return new JSONObject(new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8));}
 public static void main(String[] args)throws Exception{
  File root=Files.createTempDirectory(Paths.get(args[0]),"phira-original-").toFile();new File(root,"data").mkdir();File data=new File(root,"data/data.json");
  JSONObject initial=new JSONObject("{\"tokens\":[\"fixture-token\"],\"me\":{\"id\":123},\"config\":{\"offlineMode\":true,\"mods\":\"FLIP_X\"},\"local_records\":{\"one\":{\"score\":800000}},\"charts\":[{\"local_path\":\"custom/one\",\"record\":{\"score\":800000}}],\"respacks\":[\"original-skin\"]}");write(data,initial);byte[] before=Files.readAllBytes(data.toPath());
  check(LabStore.prepareOriginal(root).equals(root.getCanonicalFile()),"engine path changed");check(java.util.Arrays.equals(before,Files.readAllBytes(data.toPath())),"startup rewrote original data");
  File meta=new File(root,"phira-module-backups"),backup=new File(meta,"original-data-before-module.json");check(java.util.Arrays.equals(before,Files.readAllBytes(backup.toPath())),"exact backup missing");check(!new File(root,"phira-lab-082").exists(),"created independent engine");
  LabStore.beginOriginalAutoplay(root);JSONObject live=read(data);live.put("local_records",new JSONObject("{\"generated\":{\"score\":1000000}}"));live.getJSONArray("charts").getJSONObject(0).put("record",new JSONObject("{\"score\":1000000}"));live.getJSONArray("charts").put(new JSONObject("{\"local_path\":\"custom/new\",\"record\":{\"score\":1000000}}"));live.getJSONArray("respacks").put("new-skin");live.put("tokens",new JSONArray("[\"refreshed-fixture\"]"));live.getJSONObject("config").put("custom",true);write(data,live);
  LabStore.prepareOriginal(root);JSONObject restored=read(data);check(restored.getJSONObject("local_records").getJSONObject("one").getInt("score")==800000,"session score restore");check(!restored.getJSONObject("local_records").has("generated"),"generated score persisted");check(restored.getJSONArray("charts").length()==2&&restored.getJSONArray("charts").getJSONObject(1).isNull("record"),"new chart lost or generated record retained");check(restored.getJSONArray("respacks").length()==2&&restored.getJSONArray("tokens").getString(0).equals("refreshed-fixture")&&restored.getJSONObject("config").getBoolean("custom")&&restored.getJSONObject("config").getBoolean("offlineMode"),"non-record host data overwritten");
  LabStore.queueOriginalHistory(root,"all-ap");LabStore.prepareOriginal(root);check(read(data).getJSONArray("charts").getJSONObject(0).getJSONObject("record").getInt("score")==1000000,"original history AP not applied");LabStore.queueOriginalHistory(root,"restore");LabStore.prepareOriginal(root);check(read(data).getJSONArray("charts").getJSONObject(0).getJSONObject("record").getInt("score")==800000,"original history restore failed");check(java.util.Arrays.equals(before,Files.readAllBytes(backup.toPath())),"initial backup overwritten");
  File blocked=Files.createTempDirectory(Paths.get(args[0]),"phira-backup-blocked-").toFile();new File(blocked,"data").mkdir();File blockedData=new File(blocked,"data/data.json");write(blockedData,initial);Files.write(new File(blocked,"phira-module-backups").toPath(),new byte[]{1});boolean refused=false;try{LabStore.prepareOriginal(blocked);}catch(IOException expected){refused=true;}check(refused&&java.util.Arrays.equals(before,Files.readAllBytes(blockedData.toPath())),"backup failure changed data");
  System.out.println("PASS: original engine path/account/resources preserved; exact backup before edits; record-only session/history restore; backup failure refuses edits");
 }
}
